-- Generated by clean_target.py dari master-target.xlsx
-- Data: 130 baris, 0 NULL total
-- Kolom *_target dibulatkan ke integer (ROUND_HALF_UP)
-- Import CSV: Supabase Table Editor -> Table -> Import data from CSV
-- Atau psql:
--   \copy "master_target" from 'master-target.csv' with (format csv, header true, null 'NULL');

create table if not exists public."master_target" (
    "store_code" text primary key,
    "store_name" text,
    "total_target" bigint,
    "apple_target" bigint,
    "android_target" bigint,
    "samsung_target" bigint,
    "xiaomi_target" bigint,
    "huawei_target" bigint,
    "motorola_target" bigint,
    "oppo_target" bigint,
    "infinix_target" bigint,
    "accessories_target" bigint,
    "vas_target" bigint
);
